import requests
from langchain.tools import tool


@tool
def fetch_dns_over_https_record(resolver_url: str, domain: str, record_type: str = "A") -> dict:
    response = requests.get(
        resolver_url,
        params={"name": domain, "type": record_type},
        headers={"Accept": "application/dns-json"},
        timeout=10,
    )
    response.raise_for_status()
    data = response.json()
    answers = data.get("Answer", [])
    return {
        "domain": domain,
        "type": record_type,
        "status": data.get("Status"),
        "answers": [
            {"name": a.get("name"), "ttl": a.get("TTL"), "data": a.get("data")}
            for a in answers
        ],
    }

import httpx
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("dns-tools")


def _clean_lines(text: str) -> list:
    lines = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith(";"):
            continue
        lines.append(line)
    return lines


@mcp.tool()
def download_zone_file_snapshot(zone_url: str, max_records: int = 200) -> dict:
    with httpx.Client(timeout=15, follow_redirects=True) as client:
        resp = client.get(zone_url)
        resp.raise_for_status()
    records = _clean_lines(resp.text)
    return {
        "source": zone_url,
        "total": len(records),
        "records": records[:max_records],
    }

import json
import urllib.request
import urllib.parse
from agents import function_tool


def _pick(data: dict, *keys):
    for key in keys:
        if key in data:
            return data[key]
    return None


@function_tool
def check_domain_whois_via_api(api_url: str, domain: str) -> dict:
    query = urllib.parse.urlencode({"domain": domain})
    full_url = api_url + "?" + query
    with urllib.request.urlopen(full_url, timeout=10) as resp:
        payload = json.loads(resp.read().decode("utf-8"))
    return {
        "domain": domain,
        "registrar": _pick(payload, "registrar", "registrar_name"),
        "created": _pick(payload, "creation_date", "created"),
        "expires": _pick(payload, "expiry_date", "expires"),
    }
